const s = $('Score Creative').first().json;
const ranked = (s.scored || []).filter(x => x.score != null).sort((a, b) => b.score - a.score);
return [{ json: {
  period: { to: new Date().toISOString(), window_days: 1 },
  assets_scored: ranked.length,
  top: ranked.slice(0, 3).map(x => ({ channel: x.channel, score: Number(x.score.toFixed(3)), confidence: Number(x.confidence.toFixed(2)), impressions: x.impressions })),
  bottom: ranked.slice(-3).map(x => ({ channel: x.channel, score: Number(x.score.toFixed(3)), impressions: x.impressions })),
  proposals: $('Propose Playbook Update').first()?.json?.proposals || [],
  note: s.note || null
} }];
